    public void ShowToday()=>ShowDay(DateOnly.FromDateTime(DateTime.Today));
    public void ShowDay(DateOnly value){overdue=false;day=value;calendar.GoTo(value);Render();}
    public void VoiceDraft(string text,bool submit){entry.Text=text;if(submit)Add();else entry.Focus();}
    protected override bool ProcessCmdKey(ref Message m,Keys key){if(key==(Keys.Control|Keys.Z)&&!entry.Focused){Run(()=>{store.Undo();Render();});return true;}return base.ProcessCmdKey(ref m,key);}
